INSERT INTO departments (id, name, description, created_at) VALUES ('dc8c10dc-0fc2-48d9-b706-2a709b83df9a', 'Enfermarias Posto 1', 'Internação Terréo', '2025-11-30 17:06:33.930893+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('a5476766-2123-4790-8794-16648bb61235', 'Enfermaria Posto 3', 'Internação 2 Andar', '2025-11-30 17:28:34.398273+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('4e79d49b-3e0d-414d-9cef-54e8a752293b', 'Médico Clincos Plantonista', 'Médico Clínicos Plantonistas', '2025-11-30 18:27:31.202552+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('c1907ed6-1fce-46ba-b489-6f6ed7b99a3e', 'Hotelaria', 'Responsável por proporcionar uma experiência positiva aos pacientes e acompanhantes, contribuindo para a recuperação da saúde e a satisfação com o atendimento.', '2025-12-01 17:03:29.638142+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('b90c4d7c-9c67-4ec4-8b7d-e53fac0c6d5e', 'Higienização', 'Responsável pela limpeza e desinfecção realizadas diariamente, quando o paciente encontra-se internado, incluindo pisos, instalações sanitárias, superfícies horizontais de equipamentos e mobiliários, esvaziamento e troca de recipientes de Resíduos de Serviços de Saúde.', '2025-12-01 17:04:30.447553+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('f33df0fc-3811-4e7c-be46-2533e553cfa5', 'Transportes', 'Fornece transporte sanitário em ambulâncias ou outros veículos a pacientes', '2025-12-02 17:00:47.88974+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('100651d9-c5c9-4bcf-9017-26a1dd835f81', 'Radiologia', 'Área com foco no uso da radiação para fins diagnósticos e exames de imagem', '2025-12-02 17:11:43.256918+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('3b1347db-ffde-4d86-8c4a-c99eecc52ed0', 'Fisioterapia', 'Atua na recuperação de lesões musculoesqueléticas, fraturas, entorses e pós-operatórios. O fisioterapeuta aplica técnicas manuais e exercícios terapêuticos para restaurar a funcionalidade dos tecidos afetados.', '2025-12-02 17:44:50.900768+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('35f5534c-983c-4d79-96d9-b478cff6cb1c', 'Manutenção/Eng.Clínica', 'Manutenção Hospitalar', '2025-12-02 18:30:02.826394+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('e54e7192-afad-4ffe-90b5-6f6f93f2a7b8', 'Transporte/Patrimônio', 'Quem arquiva e organiza documentos, elabora relatórios, emite notas fiscais, controla correspondências, gerencia agendas e assume outras funções assistenciais que facilitam o trabalho de setores e lideranças.', '2025-12-02 18:35:09.396518+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('475488da-9601-4fb4-8039-71215065022c', 'Serviço Social', 'Analisam, elaboram, coordenam e executam planos, programas e projetos para viabilizar os direitos da população e seu acesso às políticas sociais, como a saúde, a educação, a previdência social, a habitação, a assistência social e a cultura.', '2025-12-02 18:49:44.285401+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('b4eac728-7706-4fa1-ab00-4c585800426e', 'Psicologia', 'Auxiliar o paciente em seu processo de adoecimento, visando à minimização do sofrimento provocado pela hospitalização. O profissional presta assistência não apenas ao paciente, mas também aos familiares e à equipe de saúde.', '2025-12-02 19:17:08.024244+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('7297bba6-2d72-4223-a94d-0e6f317a1a15', 'Ouvidoria', 'Concebidas como uma instância para possibilitar a participação dos cidadãos e aprimorar o controle social sobre as instituições públicas, as ouvidorias públicas promovem e garantem os direitos de cidadania, por meio do diálogo e da prestação de contas.', '2025-12-03 14:23:19.645711+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('ea319772-7639-4672-96d2-3a4f47b8ab0d', 'CAF', 'A Central de Abastecimento Farmacêutico (CAF) é o local que concentra todas as atividades relacionadas à seleção, programação, aquisição, armazenamento e distribuição de medicamentos e correlatos no município.', '2025-12-03 16:57:14.454948+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('c224297a-7f88-4a0c-b3f7-26c2d44a1052', 'Farmácia', '', '2025-12-03 17:03:07.53166+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('9ed1d46c-ce47-486a-901f-38a8ab1ec34d', 'Almoxarifado', '', '2025-12-05 12:39:21.966915+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('c2f70ae3-e27d-48fd-93d6-2513f4d5b5de', 'SIAST', '', '2025-12-05 12:39:47.748453+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('55bbd3f6-d677-4aa2-a551-202f0978b438', 'SCIH', 'Serviço de Controle de Infecção Hospitalar, implantado de acordo com as normas da vigilância sanitária, é responsável por executar as atividades definidas pela CCIH (Comissão de Controle de Infecção hospitalar).', '2025-12-05 14:41:37.540014+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('32924fb3-7b72-4389-93d9-3f30b219805d', 'NSP', 'Núcleo de Segurança do Paciente', '2025-12-05 14:49:19.170613+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('ca2a786c-2843-494e-b890-07f6966273e6', 'SAME', '', '2025-12-05 14:55:19.594125+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO departments (id, name, description, created_at) VALUES ('3490fb6f-ee14-42c9-b7d3-57da551745da', 'Faturamento', 'Gerencia todos os processos financeiros relacionados aos serviços médicos prestados. A equipe é responsável por otimizar o fluxo de caixa da instituição, garantir a conformidade das cobranças e maximizar o retorno financeiro.', '2025-12-05 15:03:11.307211+00') ON CONFLICT (id) DO NOTHING;
