-- =============================================================================
-- EXPORTAÇÃO COMPLETA DO BANCO DE DADOS
-- Sistema de Gestão de Escalas Hospitalares
-- Gerado em: 2026-03-25
-- 
-- INSTRUÇÕES DE USO:
-- 1. Este script deve ser executado num novo projeto Supabase
-- 2. Execute via SQL Editor do Supabase ou psql
-- 3. As senhas dos usuários estão em formato bcrypt (já criptografadas)
-- 4. Execute as seções em ordem para respeitar as dependências
-- =============================================================================

-- =============================================================================
-- SECTION 2: EXTENSIONS
-- =============================================================================
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- =============================================================================
-- SECTION 3: CREATE TABLES DDL
-- =============================================================================

CREATE TABLE IF NOT EXISTS user_roles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL UNIQUE,
  description text NOT NULL,
  permissions jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS departments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  description text DEFAULT '',
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS companies (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  cnpj text UNIQUE,
  active boolean DEFAULT true,
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS professional_categories (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL UNIQUE,
  color text DEFAULT '#3B82F6',
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS establishments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employer_name text NOT NULL,
  employer_document text NOT NULL,
  employer_document_type text NOT NULL DEFAULT 'CNPJ' CHECK (employer_document_type = ANY (ARRAY['CNPJ','CPF'])),
  cei_caepf_cno text,
  address_street text NOT NULL,
  address_number text,
  address_complement text,
  address_neighborhood text,
  address_city text NOT NULL,
  address_state text NOT NULL,
  address_zip text NOT NULL,
  timezone text NOT NULL DEFAULT 'America/Sao_Paulo',
  rep_p_registration text,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS system_users (
  id uuid PRIMARY KEY,
  email text NOT NULL UNIQUE,
  full_name text NOT NULL,
  role_id uuid NOT NULL REFERENCES user_roles(id),
  active boolean DEFAULT true,
  last_login timestamptz,
  created_at timestamptz DEFAULT now(),
  created_by uuid REFERENCES system_users(id),
  updated_at timestamptz DEFAULT now(),
  allowed_departments uuid[]
);

CREATE TABLE IF NOT EXISTS professionals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid,
  full_name text NOT NULL,
  category_id uuid REFERENCES professional_categories(id),
  department_id uuid REFERENCES departments(id),
  registration_number text,
  phone text,
  email text,
  active boolean DEFAULT true,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  contracted_hours_per_month integer NOT NULL DEFAULT 180,
  company_id uuid REFERENCES companies(id),
  establishment_id uuid REFERENCES establishments(id),
  pis_number text,
  hire_date date,
  cpf text
);

CREATE TABLE IF NOT EXISTS holidays (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  date date NOT NULL,
  type text DEFAULT 'Nacional' CHECK (type = ANY (ARRAY['Nacional','Estadual','Municipal'])),
  recurring boolean DEFAULT false,
  active boolean DEFAULT true,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS meal_category_config (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  category_id uuid NOT NULL UNIQUE REFERENCES professional_categories(id),
  has_meal_benefit boolean NOT NULL DEFAULT false,
  notes text DEFAULT '',
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS hour_bank_config (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id uuid UNIQUE REFERENCES companies(id),
  agreement_type text NOT NULL DEFAULT 'individual' CHECK (agreement_type = ANY (ARRAY['individual','coletivo','mensal'])),
  compensation_period_months integer NOT NULL DEFAULT 6 CHECK (compensation_period_months = ANY (ARRAY[1,6,12])),
  daily_overtime_limit_minutes integer NOT NULL DEFAULT 120,
  weekly_overtime_limit_minutes integer NOT NULL DEFAULT 600,
  monthly_overtime_limit_minutes integer NOT NULL DEFAULT 2400,
  overtime_multiplier numeric NOT NULL DEFAULT 1.50 CHECK (overtime_multiplier >= 1.50),
  sunday_multiplier numeric NOT NULL DEFAULT 2.00 CHECK (sunday_multiplier >= 1.00),
  holiday_multiplier numeric NOT NULL DEFAULT 2.00 CHECK (holiday_multiplier >= 1.00),
  night_shift_multiplier numeric NOT NULL DEFAULT 1.20,
  night_shift_start time NOT NULL DEFAULT '22:00:00',
  night_shift_end time NOT NULL DEFAULT '05:00:00',
  allow_negative_balance boolean NOT NULL DEFAULT true,
  max_negative_balance_minutes integer NOT NULL DEFAULT 480,
  auto_calculate boolean NOT NULL DEFAULT true,
  expiration_warning_days integer NOT NULL DEFAULT 30,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS monthly_schedules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  department_id uuid NOT NULL REFERENCES departments(id),
  month date NOT NULL,
  name text NOT NULL,
  status text DEFAULT 'Rascunho' CHECK (status = ANY (ARRAY['Rascunho','Publicada','Fechada'])),
  created_by uuid,
  published_at timestamptz,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS shifts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  professional_id uuid REFERENCES professionals(id),
  department_id uuid REFERENCES departments(id),
  shift_date date NOT NULL,
  start_time time NOT NULL,
  end_time time NOT NULL,
  shift_type text NOT NULL,
  status text DEFAULT 'Agendado',
  notes text DEFAULT '',
  created_by uuid,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  schedule_id uuid REFERENCES monthly_schedules(id)
);

CREATE TABLE IF NOT EXISTS nsr_sequences (
  establishment_id uuid PRIMARY KEY REFERENCES establishments(id),
  current_nsr bigint NOT NULL DEFAULT 0,
  last_updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS punch_records (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  nsr bigint NOT NULL,
  establishment_id uuid NOT NULL REFERENCES establishments(id),
  professional_id uuid NOT NULL REFERENCES professionals(id),
  punch_type text NOT NULL CHECK (punch_type = ANY (ARRAY['ENTRY','EXIT','MEAL_START','MEAL_END'])),
  punch_datetime timestamptz NOT NULL,
  server_datetime timestamptz NOT NULL DEFAULT now(),
  timezone text NOT NULL DEFAULT 'America/Sao_Paulo',
  is_outside_schedule boolean NOT NULL DEFAULT false,
  schedule_alert text,
  device_id text,
  device_type text CHECK (device_type = ANY (ARRAY['WEB','MOBILE','KIOSK','API'])),
  ip_address inet,
  user_agent text,
  latitude numeric,
  longitude numeric,
  geo_accuracy numeric,
  biometric_verification_id uuid,
  biometric_confidence numeric,
  liveness_verified boolean NOT NULL DEFAULT false,
  photo_url text,
  photo_hash text,
  previous_record_id uuid REFERENCES punch_records(id),
  previous_hash text,
  record_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  is_online boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS punch_receipts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  punch_record_id uuid NOT NULL REFERENCES punch_records(id),
  receipt_content jsonb NOT NULL,
  pdf_url text,
  pdf_hash text,
  signature_type text DEFAULT 'PAdES',
  signed_at timestamptz,
  verification_code text NOT NULL UNIQUE,
  verification_url text,
  created_at timestamptz NOT NULL DEFAULT now(),
  accessed_at timestamptz,
  access_count integer NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS punch_adjustments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  original_punch_id uuid REFERENCES punch_records(id),
  professional_id uuid NOT NULL REFERENCES professionals(id),
  establishment_id uuid NOT NULL REFERENCES establishments(id),
  adjustment_type text NOT NULL CHECK (adjustment_type = ANY (ARRAY['INCLUSION','DISREGARD','PRE_ASSIGNED','CORRECTION'])),
  adjusted_datetime timestamptz,
  adjusted_punch_type text CHECK (adjusted_punch_type = ANY (ARRAY['ENTRY','EXIT','MEAL_START','MEAL_END'])),
  justification text NOT NULL,
  supporting_document_url text,
  requested_by uuid NOT NULL REFERENCES system_users(id),
  requested_at timestamptz NOT NULL DEFAULT now(),
  approved_by uuid REFERENCES system_users(id),
  approved_at timestamptz,
  approval_status text NOT NULL DEFAULT 'PENDING' CHECK (approval_status = ANY (ARRAY['PENDING','APPROVED','REJECTED'])),
  rejection_reason text,
  adjustment_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS punch_audit_log (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  entity_type text NOT NULL,
  entity_id uuid NOT NULL,
  action text NOT NULL,
  action_details jsonb,
  user_id uuid,
  user_email text,
  ip_address inet,
  user_agent text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS shift_swaps (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  original_shift_id uuid REFERENCES shifts(id),
  requesting_professional_id uuid REFERENCES professionals(id),
  target_professional_id uuid REFERENCES professionals(id),
  offered_shift_id uuid REFERENCES shifts(id),
  reason text NOT NULL,
  status text DEFAULT 'Pendente',
  requested_at timestamptz DEFAULT now(),
  responded_at timestamptz,
  approved_by uuid,
  approved_at timestamptz,
  notes text DEFAULT '',
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS shift_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  shift_id uuid REFERENCES shifts(id),
  action_type text NOT NULL,
  performed_by uuid,
  details jsonb DEFAULT '{}',
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS meal_schedules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  shift_id uuid NOT NULL UNIQUE REFERENCES shifts(id),
  professional_id uuid NOT NULL REFERENCES professionals(id),
  shift_date date NOT NULL,
  shift_type text NOT NULL,
  shift_hours numeric NOT NULL DEFAULT 0,
  has_breakfast boolean DEFAULT false,
  has_lunch boolean DEFAULT false,
  has_dinner boolean DEFAULT false,
  has_supper boolean DEFAULT false,
  total_meals integer DEFAULT 0,
  generated_at timestamptz DEFAULT now(),
  created_by uuid
);

CREATE TABLE IF NOT EXISTS timesheet_records (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  professional_id uuid NOT NULL REFERENCES professionals(id),
  shift_id uuid REFERENCES shifts(id),
  check_in_time timestamptz NOT NULL DEFAULT now(),
  check_out_time timestamptz,
  check_in_photo_url text NOT NULL,
  check_out_photo_url text,
  status text NOT NULL DEFAULT 'Em andamento',
  notes text,
  created_at timestamptz DEFAULT now(),
  meal_break_start timestamptz,
  meal_break_end timestamptz,
  meal_break_start_photo_url text,
  meal_break_end_photo_url text
);

CREATE TABLE IF NOT EXISTS professional_facial_data (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  professional_id uuid NOT NULL UNIQUE REFERENCES professionals(id),
  facial_image_url text,
  facial_descriptors jsonb,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS hour_bank_entries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  professional_id uuid NOT NULL REFERENCES professionals(id),
  entry_date date NOT NULL,
  entry_type text NOT NULL CHECK (entry_type = ANY (ARRAY['credit','debit','compensation','expiration','adjustment'])),
  minutes integer NOT NULL,
  balance_after integer NOT NULL DEFAULT 0,
  source text NOT NULL DEFAULT 'manual' CHECK (source = ANY (ARRAY['automatic','manual','compensation','system'])),
  punch_record_id uuid REFERENCES punch_records(id),
  description text,
  multiplier_applied numeric DEFAULT 1.00,
  original_minutes integer,
  expires_at date,
  compensated_at date,
  created_by uuid REFERENCES system_users(id),
  approved_by uuid REFERENCES system_users(id),
  approved_at timestamptz,
  status text NOT NULL DEFAULT 'pending' CHECK (status = ANY (ARRAY['pending','approved','rejected','expired','compensated'])),
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS hour_bank_compensations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  professional_id uuid NOT NULL REFERENCES professionals(id),
  compensation_date date NOT NULL,
  minutes_compensated integer NOT NULL,
  compensation_type text NOT NULL CHECK (compensation_type = ANY (ARRAY['folga','saida_antecipada','entrada_tardia','dia_parcial'])),
  description text,
  entry_ids uuid[] DEFAULT '{}',
  requested_by uuid REFERENCES system_users(id),
  approved_by uuid REFERENCES system_users(id),
  approved_at timestamptz,
  status text NOT NULL DEFAULT 'pending' CHECK (status = ANY (ARRAY['pending','approved','rejected','cancelled'])),
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS export_jobs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  export_type text NOT NULL CHECK (export_type = ANY (ARRAY['AFD','AEJ','MIRROR','CUSTOM'])),
  establishment_id uuid REFERENCES establishments(id),
  start_date date NOT NULL,
  end_date date NOT NULL,
  professional_ids uuid[],
  status text NOT NULL DEFAULT 'PENDING' CHECK (status = ANY (ARRAY['PENDING','PROCESSING','COMPLETED','FAILED'])),
  progress integer DEFAULT 0,
  error_message text,
  file_url text,
  file_hash text,
  signature_file_url text,
  requested_by uuid NOT NULL REFERENCES system_users(id),
  requested_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  is_fiscal_request boolean NOT NULL DEFAULT false,
  fiscal_protocol text
);

CREATE TABLE IF NOT EXISTS audit_logs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  table_name text NOT NULL,
  record_id uuid NOT NULL,
  action text NOT NULL CHECK (action = ANY (ARRAY['INSERT','UPDATE','DELETE'])),
  old_data jsonb,
  new_data jsonb,
  changed_fields text[],
  user_id uuid,
  user_email text,
  ip_address text,
  user_agent text,
  description text,
  created_at timestamptz DEFAULT now()
);

